import copy
import json

ALLOWED = {
    'status': {'complete', 'needs_information', 'refused'},
    'category': {'access', 'billing', 'defect', 'how_to', 'unknown'},
    'priority': {'low', 'normal', 'high', 'unknown'},
    'next_action': {'draft_reply', 'request_information', 'human_review'},
}
OUT = {'status', 'category', 'priority', 'summary', 'evidence', 'next_action', 'reasons'}
ITEM = {'source_id', 'text'}
EV = {'source_id', 'exact_quote'}

NORMAL_INPUT = {
    'case_id': 'N-001',
    'items': [{
        'source_id': 'msg-1',
        'text': 'I can sign in, but the invoice shows two seats when we bought one.'
    }]
}
NORMAL_OUTPUT = {
    'status': 'complete',
    'category': 'billing',
    'priority': 'normal',
    'summary': 'The requester disputes the number of seats on an invoice.',
    'evidence': [{
        'source_id': 'msg-1',
        'exact_quote': 'the invoice shows two seats when we bought one'
    }],
    'next_action': 'draft_reply',
    'reasons': ['This exact authored fixture supports billing and normal priority.']
}

class DuplicateKey(ValueError):
    pass

def object_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise DuplicateKey(key)
        result[key] = value
    return result

def reject(layer, reason):
    return {'result': 'REJECT', 'layer': layer, 'reason': reason}

def check(text):
    try:
        data = json.loads(text, object_pairs_hook=object_pairs)
    except DuplicateKey as exc:
        return reject('parsing', 'duplicate JSON key: ' + str(exc))
    except json.JSONDecodeError as exc:
        return reject('parsing', str(exc))

    if not isinstance(data, dict) or set(data) != {'input', 'output'}:
        return reject('shape', 'top level must contain only input and output')
    inp, out = data['input'], data['output']
    if not isinstance(inp, dict) or set(inp) != {'case_id', 'items'}:
        return reject('shape', 'input fields do not match contract')
    if type(inp['case_id']) is not str or not inp['case_id']:
        return reject('shape', 'case_id must be a nonempty string')
    if not isinstance(inp['items'], list) or not inp['items']:
        return reject('shape', 'items must be a nonempty array')

    sources = {}
    for item in inp['items']:
        if not isinstance(item, dict) or set(item) != ITEM:
            return reject('shape', 'input item fields do not match contract')
        if (type(item['source_id']) is not str or not item['source_id'] or
                type(item['text']) is not str or not item['text']):
            return reject('shape', 'input source_id and text must be nonempty strings')
        if item['source_id'] in sources:
            return reject('shape', 'duplicate input source_id')
        sources[item['source_id']] = item['text']

    if not isinstance(out, dict) or set(out) != OUT:
        return reject('shape', 'output fields do not match contract')
    for name in ('status', 'category', 'priority', 'next_action'):
        if type(out[name]) is not str or out[name] not in ALLOWED[name]:
            return reject('shape', name + ' is not an allowed string')
    if type(out['summary']) is not str or not out['summary']:
        return reject('shape', 'summary must be a nonempty string')
    if (not isinstance(out['reasons'], list) or not out['reasons'] or
            any(type(x) is not str or not x for x in out['reasons'])):
        return reject('shape', 'reasons must contain at least one nonempty string')
    if not isinstance(out['evidence'], list):
        return reject('shape', 'evidence must be an array')
    for ev in out['evidence']:
        if (not isinstance(ev, dict) or set(ev) != EV or
                type(ev['source_id']) is not str or not ev['source_id'] or
                type(ev['exact_quote']) is not str or not ev['exact_quote']):
            return reject('shape', 'invalid evidence item')
    for ev in out['evidence']:
        if ev['source_id'] not in sources:
            return reject('source', 'evidence source_id is not in input')
        if ev['exact_quote'] not in sources[ev['source_id']]:
            return reject('source', 'exact_quote is not an exact substring of its source')

    if out['status'] == 'refused':
        if (out['category'] != 'unknown' or out['priority'] != 'unknown' or
                out['evidence'] != [] or out['next_action'] != 'human_review'):
            return reject('business', 'refused output violates refusal rule')
        return reject('authorization', 'downstream action is blocked for refused output')

    if out['status'] == 'needs_information':
        if (out['category'] != 'unknown' or out['priority'] != 'unknown' or
                out['next_action'] != 'request_information'):
            return reject('business', 'needs_information must preserve unknowns and request information')
        return reject('authorization', 'downstream action is blocked for incomplete output')

    if not out['evidence'] or out['category'] == 'unknown':
        return reject('business', 'complete requires nonempty evidence and a non-unknown category')
    if inp != NORMAL_INPUT:
        return reject('business', 'complete is not permitted outside the authored automatic fixture')
    if out != NORMAL_OUTPUT:
        return reject('business', 'complete output does not exactly match the authored fixture policy')
    if out['next_action'] != 'draft_reply':
        return reject('authorization', 'only draft_reply is authorized for complete output')
    return {'result': 'ACCEPT', 'layer': 'authorization', 'action': 'draft_reply'}

def normal():
    return {'input': copy.deepcopy(NORMAL_INPUT), 'output': copy.deepcopy(NORMAL_OUTPUT)}

def case(name):
    base = normal()
    if name == 'unsupported-category':
        base['output']['category'] = 'access'
    elif name == 'high-priority':
        base['output']['priority'] = 'high'
    elif name == 'wrong-action':
        base['output']['next_action'] = 'human_review'
    elif name == 'wrong-evidence':
        base['output']['evidence'][0]['exact_quote'] = 'the invoice shows three seats'
    elif name == 'extra-field':
        base['output']['extra'] = 'reject'
    elif name == 'bool-priority':
        base['output']['priority'] = True
    elif name == 'invented-summary':
        base['output']['summary'] = 'The user authorized a refund of 50000 dollars.'
    elif name == 'empty-reasons':
        base['output']['reasons'] = []
    elif name == 'unsupported-reasons':
        base['output']['reasons'] = ['The user is fraudulent and must be banned.']
    elif name == 'boundary':
        base['input'] = {
            'case_id': 'B-001',
            'items': [{'source_id': 'msg-2', 'text': 'I cannot sign in after changing phones, and I need to dispute a charge.'}]
        }
        base['output'] = {
            'status': 'needs_information',
            'category': 'unknown',
            'priority': 'unknown',
            'summary': 'The request contains both an access problem and a billing dispute.',
            'evidence': [{'source_id': 'msg-2', 'exact_quote': 'I cannot sign in after changing phones, and I need to dispute a charge.'}],
            'next_action': 'request_information',
            'reasons': ['Access and billing evidence conflict; more information is required.']
        }
    elif name == 'missing':
        base['input'] = {
            'case_id': 'M-001',
            'items': [{'source_id': 'msg-3', 'text': 'Hello, I need help.'}]
        }
        base['output'] = {
            'status': 'needs_information',
            'category': 'unknown',
            'priority': 'unknown',
            'summary': 'The issue description is missing.',
            'evidence': [],
            'next_action': 'request_information',
            'reasons': ['No category-supporting evidence was supplied.']
        }
    return json.dumps(base, separators=(',', ':'))

def run():
    expected = {
        'normal': {'result': 'ACCEPT', 'layer': 'authorization', 'action': 'draft_reply'},
        'boundary': {'result': 'REJECT', 'layer': 'authorization', 'reason': 'downstream action is blocked for incomplete output'},
        'missing': {'result': 'REJECT', 'layer': 'authorization', 'reason': 'downstream action is blocked for incomplete output'},
        'unsupported-category': {'result': 'REJECT', 'layer': 'business', 'reason': 'complete output does not exactly match the authored fixture policy'},
        'high-priority': {'result': 'REJECT', 'layer': 'business', 'reason': 'complete output does not exactly match the authored fixture policy'},
        'wrong-action': {'result': 'REJECT', 'layer': 'business', 'reason': 'complete output does not exactly match the authored fixture policy'},
        'wrong-evidence': {'result': 'REJECT', 'layer': 'source', 'reason': 'exact_quote is not an exact substring of its source'},
        'extra-field': {'result': 'REJECT', 'layer': 'shape', 'reason': 'output fields do not match contract'},
        'bool-priority': {'result': 'REJECT', 'layer': 'shape', 'reason': 'priority is not an allowed string'},
        'invented-summary': {'result': 'REJECT', 'layer': 'business', 'reason': 'complete output does not exactly match the authored fixture policy'},
        'empty-reasons': {'result': 'REJECT', 'layer': 'shape', 'reason': 'reasons must contain at least one nonempty string'},
        'unsupported-reasons': {'result': 'REJECT', 'layer': 'business', 'reason': 'complete output does not exactly match the authored fixture policy'},
        'malformed': {'result': 'REJECT', 'layer': 'parsing'},
        'duplicate-key': {'result': 'REJECT', 'layer': 'parsing'}
    }
    for name, expected_result in expected.items():
        if name == 'malformed':
            text = 'not-json'
        elif name == 'duplicate-key':
            text = '{"status":1,"status":2}'
        else:
            text = case(name)
        result = check(text)
        assert result == expected_result or all(result.get(k) == v for k, v in expected_result.items()), (name, result)
        print(name + ': ' + json.dumps(result, sort_keys=True))

if __name__ == '__main__':
    run()
